import sys
from collections import defaultdict

class SumCalculator:
    def __init__(self):
        self.total = 0

    def add(self, num):
        if isinstance(num, int):
            self.total += num
        else:
            raise ValueError("Cannot add non-integers")

    def get_total(self):
        return self.total

def fast_sum(nums):
    calculator = SumCalculator()
    for num in nums:
        calculator.add(num)
