from multiprocessing import Process, Pipe

class FastSum:
    def __init__(self):
        self.n = len(self.numbers)
        self.pipes = [Pipe() for _ in range(self.n)]
        self.procs = [Process(target=self._worker, args=(i,)) for i in range(self.n)]

    def _worker(self, idx):
        p1, p2 = self.pipes[idx]
        for num in self.numbers:
            p1.send(num)
        p1.close()
        p2.send(0)

    def __del__(self):
        for p in self.procs:
            p.terminate()

    def get_result(self):
        return reduce(lambda x, y: x + y, [p2.recv() for p2 in self.pipes])

def fast_sum(numbers):
